import {
  ArrowLeftRight,
  ChevronsUpDown,
  ExternalLink,
  LogOut,
} from "lucide-react";

import { cn } from "@/lib/utils";
import {
  AvatarFallback,
  AvatarImage,
  AvatarRoot,
} from "@/registry/thornberry/components/avatar";
import {
  MenuContent,
  MenuItem,
  MenuItemGroup,
  MenuItemGroupLabel,
  MenuItemText,
  MenuPositioner,
  MenuRoot,
  MenuSeparator,
  MenuTrigger,
} from "@/registry/thornberry/components/menu";

import type { ComponentProps, ReactNode } from "react";

/** The signed-in user the account menu belongs to */
interface AccountMenuUser {
  name?: string | null;
  email?: string | null;
  /** Avatar URL, if set; falls back to initials */
  image?: string | null;
}

/**
 * Up to two initials for an avatar fallback: the first letters of the first
 * and last words of the name, else the first letter of the email, else "?"
 * @param name - The user's display name
 * @param email - The user's email, used when the name is blank
 */
const getInitials = (name?: string | null, email?: string | null): string => {
  const words = (name ?? "").trim().split(/\s+/).filter(Boolean);
  const first = words[0];

  if (first) {
    const last = words.length > 1 ? words[words.length - 1] : undefined;
    // Array.from splits by code point, so an emoji or astral letter stays whole
    const initials =
      (Array.from(first)[0] ?? "") + (last ? (Array.from(last)[0] ?? "") : "");

    return initials.toUpperCase();
  }

  const fromEmail = Array.from((email ?? "").trim())[0];

  return fromEmail ? fromEmail.toUpperCase() : "?";
};

/**
 * An entry in the account menu. A menu item with a touch-sized target; wrap an
 * app's router link with `asChild` to make it a destination
 */
const AccountMenuItem = ({
  className,
  ...rest
}: ComponentProps<typeof MenuItem>) => (
  <MenuItem
    className={cn("justify-start pointer-coarse:min-h-11", className)}
    {...rest}
  />
);

interface AccountMenuProps {
  /** The signed-in user */
  user: AccountMenuUser;
  /** Signs the user out; offered as the last entry */
  onSignOut: () => void;
  /**
   * Switches to another Omni account (the app re-runs sign-in with
   * `prompt=select_account`, which shows the account picker); offered just
   * above Sign out when set
   */
  onSwitchAccount?: () => void;
  switchAccountLabel?: string;
  /** App destinations (`AccountMenuItem`s), listed under the user's name */
  children?: ReactNode;
  /** Link to the shared Omni account hub, opened in a new tab when set */
  manageAccountUrl?: string;
  manageAccountLabel?: string;
  signOutLabel?: string;
  /**
   * Trigger layout: "avatar" is the round avatar for a header; "sidebar" is a
   * full-width row with the avatar, name, and email for a sidebar footer (it
   * shrinks to the avatar in a collapsed icon sidebar). Defaults to "avatar"
   */
  variant?: "avatar" | "sidebar";
  /** Accessible name of the avatar trigger (the sidebar row is named by its text) */
  triggerLabel?: string;
  /** Avatar size in the trigger. Defaults to "sm", or "xs" in the sidebar row */
  avatarSize?: ComponentProps<typeof AvatarRoot>["size"];
  /** Classes for the avatar trigger */
  className?: string;
  /** Classes for the menu panel */
  contentClassName?: string;
  /**
   * Menu placement relative to the trigger. Defaults to below, end-aligned for
   * the avatar, and to the right, bottom-aligned for the sidebar row
   */
  positioning?: ComponentProps<typeof MenuRoot>["positioning"];
}

/**
 * The standard Omni account menu: the signed-in user's avatar (initials while
 * no image loads), opening a menu headed by their name and email, with the
 * app's destinations, an optional link to the Omni account hub, an optional
 * Switch account, and Sign out.
 *
 * Presentational and router-agnostic: the host app passes the user, its own
 * destinations as children, and the sign-out handler. Every entry is a menu
 * item, so the arrow keys, Home/End, typeahead, and Escape all work.
 *
 * @example
 * <AccountMenu user={auth.user} onSignOut={signOut} manageAccountUrl={hubUrl}>
 *   <AccountMenuItem value="/profile" asChild>
 *     <Link to="/profile">Profile</Link>
 *   </AccountMenuItem>
 * </AccountMenu>
 */
const AccountMenu = ({
  user,
  onSignOut,
  onSwitchAccount,
  switchAccountLabel = "Switch account",
  children,
  manageAccountUrl,
  manageAccountLabel = "Manage account",
  signOutLabel = "Sign out",
  variant = "avatar",
  triggerLabel = "Open account menu",
  avatarSize,
  className,
  contentClassName,
  positioning,
}: AccountMenuProps) => {
  const name = user.name?.trim() || null;
  const email = user.email?.trim() || null;
  const isSidebar = variant === "sidebar";

  const avatar = (
    <AvatarRoot size={avatarSize ?? (isSidebar ? "xs" : "sm")}>
      <AvatarImage src={user.image ?? undefined} alt="" />
      <AvatarFallback className="font-medium">
        {getInitials(name, email)}
      </AvatarFallback>
    </AvatarRoot>
  );

  return (
    <MenuRoot
      positioning={
        positioning ?? { placement: isSidebar ? "right-end" : "bottom-end" }
      }
    >
      {isSidebar ? (
        <MenuTrigger
          className={cn(
            "flex w-full items-center gap-2 overflow-hidden rounded-md p-2 text-left text-sm transition-colors hover:bg-muted data-[state=open]:bg-muted pointer-coarse:min-h-11",
            // A collapsed icon sidebar keeps just the avatar
            "group-data-[collapsible=icon]:size-8 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:p-0",
            className,
          )}
        >
          {avatar}
          {/* Visually hidden, not removed, in a collapsed icon sidebar, so the
              avatar-only row keeps the user's name as its accessible name */}
          <span className="flex min-w-0 flex-1 flex-col group-data-[collapsible=icon]:sr-only">
            <span className="truncate font-medium">{name ?? email}</span>
            {name && email && (
              <span className="text-muted-foreground truncate text-xs">
                {email}
              </span>
            )}
          </span>
          <ChevronsUpDown
            className="text-muted-foreground size-4 shrink-0 group-data-[collapsible=icon]:hidden"
            aria-hidden
          />
        </MenuTrigger>
      ) : (
        <MenuTrigger
          aria-label={triggerLabel}
          className={cn(
            // A 44px target around the avatar on touch screens
            "inline-flex shrink-0 items-center justify-center rounded-full transition-shadow hover:ring-2 hover:ring-border data-[state=open]:ring-2 data-[state=open]:ring-border pointer-coarse:size-11",
            className,
          )}
        >
          {avatar}
        </MenuTrigger>
      )}

      <MenuPositioner>
        <MenuContent className={cn("min-w-56 max-w-xs", contentClassName)}>
          <MenuItemGroup>
            {(name || email) && (
              <MenuItemGroupLabel className="flex-col items-start gap-0.5">
                <span className="w-full truncate">{name ?? email}</span>
                {name && email && (
                  <span className="text-muted-foreground w-full truncate text-xs font-normal">
                    {email}
                  </span>
                )}
              </MenuItemGroupLabel>
            )}

            {children}

            {manageAccountUrl && (
              <AccountMenuItem value="manage-account" asChild>
                <a href={manageAccountUrl} target="_blank" rel="noreferrer">
                  <MenuItemText>{manageAccountLabel}</MenuItemText>
                  <ExternalLink className="ml-auto" aria-hidden />
                </a>
              </AccountMenuItem>
            )}
          </MenuItemGroup>

          <MenuSeparator />

          {onSwitchAccount && (
            <AccountMenuItem value="switch-account" onSelect={onSwitchAccount}>
              <ArrowLeftRight aria-hidden />
              <MenuItemText>{switchAccountLabel}</MenuItemText>
            </AccountMenuItem>
          )}

          <AccountMenuItem
            value="sign-out"
            variant="destructive"
            onSelect={onSignOut}
          >
            <LogOut aria-hidden />
            <MenuItemText>{signOutLabel}</MenuItemText>
          </AccountMenuItem>
        </MenuContent>
      </MenuPositioner>
    </MenuRoot>
  );
};

export type { AccountMenuProps, AccountMenuUser };
export { AccountMenu, AccountMenuItem, getInitials };

import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

import type { ClassValue } from "clsx";

export const cn = (...inputs: ClassValue[]) => {
  return twMerge(clsx(inputs));
};

import { Avatar as ArkAvatar, useAvatar as useArkAvatar } from "@ark-ui/react";
import { cva } from "class-variance-authority";

import { cn } from "@/lib/utils";

import type { VariantProps } from "class-variance-authority";
import type { ComponentProps, ReactNode } from "react";

const avatarVariants = cva(
  "relative flex shrink-0 items-center justify-center overflow-hidden rounded-full",
  {
    variants: {
      size: {
        xs: "size-8 text-xs",
        sm: "size-9 text-sm",
        md: "text-md size-10",
        lg: "size-11 text-lg",
        xl: "size-12 text-xl",
      },
    },
    defaultVariants: { size: "md" },
  },
);

const useAvatar = useArkAvatar;

const AvatarProvider = ({
  className,
  size,
  ...rest
}: ComponentProps<typeof ArkAvatar.RootProvider> &
  VariantProps<typeof avatarVariants>) => (
  <ArkAvatar.RootProvider
    className={cn(avatarVariants({ size, className }))}
    {...rest}
  />
);

const AvatarRoot = ({
  className,
  size,
  ...rest
}: ComponentProps<typeof ArkAvatar.Root> &
  VariantProps<typeof avatarVariants>) => (
  <ArkAvatar.Root
    className={cn(avatarVariants({ size, className }))}
    {...rest}
  />
);

const AvatarFallback = ({
  className,
  ...rest
}: ComponentProps<typeof ArkAvatar.Fallback>) => (
  <ArkAvatar.Fallback
    className={cn(
      "flex size-full items-center justify-center rounded-full bg-muted",
      className,
    )}
    {...rest}
  />
);

const AvatarImage = ({
  className,
  ...rest
}: ComponentProps<typeof ArkAvatar.Image>) => (
  <ArkAvatar.Image
    // Render the image even before it decodes (overriding Ark's `hidden`) so it
    // can cross-fade in via opacity rather than snapping from display:none. Ark
    // flips `data-state` to "visible" once it loads, driving the fade; a
    // broken/loading one stays at opacity 0 with the fallback behind it.
    hidden={false}
    ref={(img) => {
      if (!img) return;
      // Only a cached, already-decoded image is shown instantly (transition
      // suppressed) so a page of cached avatars never mass-fades at once. Every
      // other case, no src, still loading, or a broken/stale src left mounted
      // by `hidden={false}` after the avatar is cleared, hands control back to
      // the data-state class so the image stays at opacity-0 and the fallback
      // shows, instead of a leftover inline opacity keeping a broken glyph or
      // the `alt` text visible until a refresh.
      if (img.getAttribute("src") && img.complete && img.naturalWidth > 0) {
        img.style.transition = "none";
        img.style.opacity = "1";
      } else {
        img.style.opacity = "";
        img.style.transition = "";
      }
    }}
    className={cn(
      // `absolute inset-0` overlays the image on the fallback instead of leaving
      // it in flow. Because `hidden={false}` keeps the <img> mounted while it
      // loads or after it errors, an in-flow image would be a second flex child
      // of the flex root and split the row with the fallback, shoving the
      // fallback initial off-center. Taking it out of flow lets the fallback own
      // the full circle so its initial stays centered.
      "absolute inset-0 aspect-square size-full object-cover opacity-0 transition-opacity duration-300 ease-out data-[state=visible]:opacity-100",
      className,
    )}
    alt="Avatar"
    {...rest}
  />
);

interface AvatarProps extends ComponentProps<typeof AvatarRoot> {
  /** Image URL; the fallback shows while it loads, or when unset or broken. */
  src?: string | null;
  alt?: string;
  /** Shown until the image loads (e.g. the user's initials). */
  fallback: ReactNode;
  imageProps?: ComponentProps<typeof AvatarImage>;
  fallbackProps?: ComponentProps<typeof AvatarFallback>;
}

/**
 * Avatar with an image and a fallback. `className` and `size` style the round
 * frame only; the image and fallback keep their own shape so a border or
 * background set on the frame is never repeated inside the clip.
 */
const Avatar = ({
  src,
  alt,
  fallback,
  imageProps,
  fallbackProps,
  ...rest
}: AvatarProps) => (
  <AvatarRoot {...rest}>
    <AvatarFallback {...fallbackProps}>{fallback}</AvatarFallback>

    <AvatarImage src={src ?? undefined} alt={alt ?? "Avatar"} {...imageProps} />
  </AvatarRoot>
);

export {
  Avatar,
  AvatarFallback,
  AvatarImage,
  type AvatarProps,
  AvatarProvider,
  AvatarRoot,
  useAvatar,
};

import { ark as arkFactory } from "@ark-ui/react/factory";
import { Menu as ArkMenu, useMenu } from "@ark-ui/react/menu";
import { Portal } from "@ark-ui/react/portal";
import { Check, ChevronRight } from "lucide-react";

import { cn } from "@/lib/utils";

import type { ark } from "@ark-ui/react";
import type { ComponentProps, ReactNode } from "react";

const MenuProvider = ArkMenu.RootProvider;
const MenuRoot = ArkMenu.Root;
const MenuContextTrigger = ArkMenu.ContextTrigger;
const PrimitiveMenuIndicator = ArkMenu.ItemIndicator;

/**
 * Opens the menu. Shows a pointer, a keyboard focus ring, and a disabled state
 * whether it renders its own button or wraps a child via `asChild`
 */
const MenuTrigger = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Trigger>) => (
  <ArkMenu.Trigger
    className={cn(
      "cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50",
      className,
    )}
    {...rest}
  />
);

const MenuPositioner = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Positioner>) => (
  <ArkMenu.Positioner className={className} {...rest} />
);

/**
 * Menu panel. Capped to the viewport space the positioner reports
 * (`--available-height`) and scrolls past it, so a long menu never runs off
 * screen with its bottom entries unreachable
 */
const MenuContent = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Content>) => (
  <ArkMenu.Content
    className={cn(
      "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 z-50 flex max-h-(--available-height) min-w-32 origin-(--transform-origin) flex-col gap-0.5 overflow-y-auto overflow-x-hidden overscroll-contain rounded-md border bg-popover p-1 text-popover-foreground shadow-md outline-none duration-300 data-[state=closed]:animate-out data-[state=open]:animate-in",
      className,
    )}
    {...rest}
  />
);

const MenuArrow = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Arrow>) => (
  <ArkMenu.Arrow className={cn("fill-popover", className)} {...rest} />
);

const MenuArrowTip = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ArrowTip>) => (
  <ArkMenu.ArrowTip className={cn("fill-border", className)} {...rest} />
);

const MenuItem = ({
  className,
  children,
  variant = "default",
  ...rest
}: ComponentProps<typeof ArkMenu.Item> & {
  variant?: "default" | "destructive";
}) => (
  <ArkMenu.Item
    data-variant={variant}
    className={cn(
      "relative flex cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden hover:bg-muted focus:bg-muted data-disabled:pointer-events-none data-[state=checked]:bg-muted data-highlighted:bg-muted data-inset:pl-8 data-[variant=destructive]:text-destructive data-disabled:opacity-50 data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive data-[variant=destructive]:hover:bg-destructive/10 dark:data-[variant=destructive]:hover:bg-destructive/20 [&[data-state=checked][data-highlighted]]:bg-muted [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 data-[variant=destructive]:*:[svg]:text-destructive!",
      variant === "destructive" &&
        "data-highlighted:bg-destructive/10 data-highlighted:text-destructive",
      className,
    )}
    {...rest}
  >
    {children}
  </ArkMenu.Item>
);

const MenuCheckboxItem = ({
  className,
  children,
  ...rest
}: ComponentProps<typeof ArkMenu.CheckboxItem>) => (
  <ArkMenu.CheckboxItem
    className={cn(
      "relative flex w-full cursor-pointer select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none hover:bg-muted focus:bg-muted data-disabled:pointer-events-none data-[state=checked]:bg-muted data-highlighted:bg-muted data-disabled:opacity-50 [&[data-state=checked][data-highlighted]]:bg-muted",
      className,
    )}
    {...rest}
  >
    {children}
  </ArkMenu.CheckboxItem>
);

const MenuItemGroup = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ItemGroup>) => (
  <ArkMenu.ItemGroup className={cn("overflow-hidden", className)} {...rest} />
);

const MenuItemGroupLabel = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ItemGroupLabel>) => (
  <ArkMenu.ItemGroupLabel
    className={cn(
      "flex w-full cursor-default items-center justify-between p-2 font-medium text-foreground text-sm",
      className,
    )}
    {...rest}
  />
);

const MenuItemText = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ItemText>) => (
  <ArkMenu.ItemText className={className} {...rest} />
);

const MenuItemIndicator = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ItemIndicator>) => (
  <ArkMenu.ItemIndicator
    className={cn(
      "ml-auto flex h-3.5 w-3.5 items-center justify-center",
      className,
    )}
    {...rest}
  >
    <Check className="size-4" />
  </ArkMenu.ItemIndicator>
);

const MenuRadioItem = ({
  className,
  children,
  ...rest
}: ComponentProps<typeof ArkMenu.RadioItem>) => (
  <ArkMenu.RadioItem
    className={cn(
      "relative flex cursor-pointer select-none items-center gap-2 rounded-sm py-1.5 pr-2 pl-8 text-sm outline-hidden hover:bg-muted focus:bg-muted data-highlighted:bg-muted data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
      className,
    )}
    {...rest}
  >
    {children}
  </ArkMenu.RadioItem>
);

const MenuRadioItemGroup = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.RadioItemGroup>) => (
  <ArkMenu.RadioItemGroup className={className} {...rest} />
);

const MenuSeparator = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Separator>) => (
  <ArkMenu.Separator
    className={cn("-mx-1 mt-1 mb-1 h-px bg-border", className)}
    {...rest}
  />
);

const MenuTriggerItem = ({
  className,
  children,
  ...rest
}: ComponentProps<typeof ArkMenu.TriggerItem>) => (
  <ArkMenu.TriggerItem
    className={cn(
      "relative flex cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none focus:bg-muted focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 data-disabled:pointer-events-none data-highlighted:bg-muted data-disabled:opacity-50 [&>svg]:size-4",
      className,
    )}
    {...rest}
  >
    {children}
    <ChevronRight className="ml-auto h-4 w-4" />
  </ArkMenu.TriggerItem>
);

// TODO: Dicuss passing in an Icon i.e, <Settings /> as children
const MenuItemShortcut = ({
  className,
  children,
  ...rest
}: ComponentProps<typeof ark.span>) => (
  <span
    className={cn(
      "ml-auto text-muted-foreground text-xs tracking-widest",
      className,
    )}
    {...rest}
  >
    {children}
  </span>
);

interface ContextMenuItem {
  label: string;
  /** Unique value; defaults to the label */
  value?: string;
  onSelect?: () => void;
  variant?: "default" | "destructive";
  disabled?: boolean;
  /** Shortcut hint shown beside the label (render it with `hotkeyLabel`) */
  shortcut?: string;
  /** Render a separator here instead of an item */
  separator?: boolean;
}

interface ContextMenuProps {
  items: ContextMenuItem[];
  /** The single element that opens the menu on right-click (rendered `asChild`) */
  children: ReactNode;
}

/**
 * Right-click menu around one element. Context menus nest (an app-wide
 * fallback, then a row's own menu), so two things keep them independent: the
 * trigger stops the event once it opens, so only the innermost menu shows, and
 * the menu context wraps only the menu itself, never `children`, so menus
 * rendered inside are not mistaken for submenus of this one
 */
const ContextMenu = ({ items, children }: ContextMenuProps) => {
  const menu = useMenu();
  const triggerProps = menu.api.getContextTriggerProps();

  return (
    <>
      <arkFactory.div
        asChild
        {...triggerProps}
        onContextMenu={(event) => {
          triggerProps.onContextMenu?.(event);
          event.stopPropagation();
        }}
      >
        {children}
      </arkFactory.div>
      <MenuProvider value={menu} lazyMount unmountOnExit>
        <Portal>
          <MenuPositioner>
            <MenuContent>
              {items.map((item, index) =>
                item.separator ? (
                  // biome-ignore lint/suspicious/noArrayIndexKey: separators have no identity of their own
                  <MenuSeparator key={`separator-${index}`} />
                ) : (
                  <MenuItem
                    key={item.value ?? item.label}
                    value={item.value ?? item.label}
                    disabled={item.disabled}
                    variant={item.variant}
                    onSelect={item.onSelect}
                  >
                    {item.label}
                    {item.shortcut && (
                      <MenuItemShortcut>{item.shortcut}</MenuItemShortcut>
                    )}
                  </MenuItem>
                ),
              )}
            </MenuContent>
          </MenuPositioner>
        </Portal>
      </MenuProvider>
    </>
  );
};

export {
  ContextMenu,
  type ContextMenuItem,
  type ContextMenuProps,
  MenuArrow,
  MenuArrowTip,
  MenuCheckboxItem,
  MenuContent,
  MenuContextTrigger,
  MenuItem,
  MenuItemGroup,
  MenuItemGroupLabel,
  MenuItemIndicator,
  MenuItemShortcut,
  MenuItemText,
  MenuPositioner,
  MenuProvider,
  MenuRadioItem,
  MenuRadioItemGroup,
  MenuRoot,
  MenuSeparator,
  MenuTrigger,
  MenuTriggerItem,
  PrimitiveMenuIndicator,
};
